    // আপনার বানানো সেই "ক্রোম-প্রো" ইঞ্জিন (একটু পলিশ করা)
    public boolean handleCustomLink(String url, android.webkit.WebView view) {
        if (url == null || url.startsWith("http://") || url.startsWith("https://") || 
            url.startsWith("file://") || url.startsWith("javascript:") || url.startsWith("about:")) {
            return false; // সাধারণ ওয়েবসাইটগুলো ব্রাউজার নিজেই খুলবে
        }

        try {
            android.content.Context context = view.getContext();
            android.content.Intent intent;

            // ১. ক্রোম স্টাইল ইউআরএল পার্সিং (intent:// স্কিম)
            if (url.startsWith("intent://")) {
                intent = android.content.Intent.parseUri(url, android.content.Intent.URI_INTENT_SCHEME);

                // অ্যাপ আছে কিনা চেক
                if (intent.resolveActivity(context.getPackageManager()) != null) {
                    context.startActivity(intent);
                    return true;
                }

                // অ্যাপ না থাকলে ওয়েবসাইটের দেওয়া fallback_url চেক করা
                String fallbackUrl = intent.getStringExtra("browser_fallback_url");
                if (fallbackUrl != null) {
                    view.loadUrl(fallbackUrl);
                    return true;
                }

                // ফলব্যাক না থাকলে সরাসরি প্লে-স্টোরে পাঠানো
                String packageName = intent.getPackage();
                if (packageName != null) {
                    android.content.Intent marketIntent = new android.content.Intent(android.content.Intent.ACTION_VIEW, android.net.Uri.parse("market://details?id=" + packageName));
                    if (marketIntent.resolveActivity(context.getPackageManager()) != null) {
                        context.startActivity(marketIntent);
                    } else {
                        view.loadUrl("https://play.google.com/store/apps/details?id=" + packageName);
                    }
                    return true;
                }
            } 
            // ২. সরাসরি স্কিম দিয়ে চেষ্টা (tel, sms, mailto, whatsapp ইত্যাদি)
            else {
                intent = new android.content.Intent(android.content.Intent.ACTION_VIEW, android.net.Uri.parse(url));
                if (intent.resolveActivity(context.getPackageManager()) != null) {
                    context.startActivity(intent);
                    return true;
                } else {
                    // অ্যাপ না থাকলে টোস্ট দেখাবে, কিন্তু Error পেজ আসতে দেবে না!
                    android.widget.Toast.makeText(context, "No app found to open this link!", android.widget.Toast.LENGTH_SHORT).show();
                    return true; // true দিলে ব্রাউজার আর জোর করে লোড করবে না
                }
            }
        } catch (Exception e) {
            // সাইলেন্ট এরর: কোনো ঝামেলা হলে ক্র্যাশ না করে চুপচাপ হজম করবে
            return true; 
        }
        return true; 
    }

    // ইঞ্জিনটাকে ব্রাউজারের সাথে কানেক্ট করার লজিক
    private void syncEngineWithBrowser() {
        android.webkit.WebView myBrowser = findViewById(R.id.browser_webview);
        if (myBrowser != null) {
            myBrowser.setWebViewClient(new android.webkit.WebViewClient() {

                // এখানে আপনার ইঞ্জিন কল হবে
                @Override
                public boolean shouldOverrideUrlLoading(android.webkit.WebView view, String url) {
                    return handleCustomLink(url, view);
                }

                // ১ নম্বর ব্লকের কাজগুলো এখানে সেভ করা হলো
                @Override
                public void onPageFinished(android.webkit.WebView view, String url) {
                    super.onPageFinished(view, url);

                    // ইউআরএল বক্স আপডেট
                    android.widget.EditText urlInput = findViewById(R.id.url_input);
                    if (urlInput != null) urlInput.setText(url);

                    // রিফ্রেশ চাকা থামানো
                    androidx.swiperefreshlayout.widget.SwipeRefreshLayout swipe = findViewById(R.id.swipe_refresh);
                    if (swipe != null) swipe.setRefreshing(false);
                }
            });
        }
    }

    {
        // অ্যাপ চালু হওয়ার ১.৫ সেকেন্ড পর ইঞ্জিনটি ব্রাউজারের সাথে সিঙ্ক হয়ে যাবে
        new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(() -> {
            syncEngineWithBrowser();
        }, 1500);
    }

